 77	<div class="calc">
 78	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
 79	  <div class="groups" data-testid="calc-groups" aria-hidden="true"></div>
 80	  <div class="keys">
 81	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open group">(</button>
 82	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close group">)</button>
 83	
 84	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
 85	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
 86	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
 87	
 88	    <button data-testid="key-7" data-digit="7">7</button>
 89	    <button data-testid="key-8" data-digit="8">8</button>
 90	    <button data-testid="key-9" data-digit="9">9</button>
 91	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
 92	
 93	    <button data-testid="key-4" data-digit="4">4</button>
 94	    <button data-testid="key-5" data-digit="5">5</button>
 95	    <button data-testid="key-6" data-digit="6">6</button>
 96	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
 97	
 98	    <button data-testid="key-1" data-digit="1">1</button>
 99	    <button data-testid="key-2" data-digit="2">2</button>
100	    <button data-testid="key-3" data-digit="3">3</button>
101	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
102	
103	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
104	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
105	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
106	  </div>
107	</div>
108	<script>
109	(function () {
110	  var display = document.querySelector('[data-testid="calc-display"]');
111	  var groupsEl = document.querySelector('[data-testid="calc-groups"]');
112	  var opButtons = document.querySelectorAll('[data-op]');
113	
114	  var state;
115	
116	  function reset() {
117	    state = {
118	      entry: '0',        // text of the number being typed
119	      value: 0,          // exact current value when not typing; never rounded
120	      stored: null,      // left operand
121	      op: null,          // pending operator
122	      typing: false,     // true while the user is building an entry
123	      edited: false,     // true when ± or ) turned the display into the entry
124	      lastOp: null,      // for repeated equals
125	      lastOperand: null,
126	      groups: [],        // one saved {stored, op} per open parenthesis
127	      error: false
128	    };
129	  }
130	
131	  function compute(a, op, b) {
132	    switch (op) {
133	      case '+': return a + b;
134	      case '-': return a - b;
135	      case '*': return a * b;
136	      case '/': return b === 0 ? NaN : a / b;
137	    }
138	    return b;
139	  }
140	
141	  function currentValue() {
142	    return state.typing ? parseFloat(state.entry) : state.value;
143	  }
144	
145	  // True when the display holds an entry: typed, or changed by ± or ).
146	  function hasEntry() {
147	    return state.typing || state.edited;
148	  }
149	
150	  // Presentation only: at most 10 significant digits, no trailing zeros,
151	  // exponential notation when |n| >= 1e10 or |n| < 1e-9. Never feed the
152	  // result back into a calculation.
153	  function format(n) {
154	    var m = Math.abs(n).toExponential(9).match(/^(\d)\.(\d+)e([+-]\d+)$/);
155	    var digits = m[1] + m[2];
156	    var exp = parseInt(m[3], 10);
157	    var sign = n < 0 ? '-' : '';
158	    var intPart, frac;
159	    if (Number(digits) === 0) return '0';
160	    if (exp >= 10 || exp < -9) {
161	      frac = m[2].replace(/0+$/, '');
162	      return sign + m[1] + (frac ? '.' + frac : '') + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
163	    }
164	    if (exp >= 0) {
165	      intPart = digits.slice(0, exp + 1);
166	      frac = digits.slice(exp + 1);
167	    } else {
168	      intPart = '0';
169	      frac = new Array(-exp).join('0') + digits;
170	    }
171	    frac = frac.replace(/0+$/, '');
172	    return sign + intPart + (frac ? '.' + frac : '');
173	  }
174	
175	  function render() {
176	    var text, value;
177	    if (state.error) {
178	      text = 'Error';
179	      value = 'NaN';
180	    } else {
181	      value = currentValue();
182	      text = state.typing ? state.entry : format(value);
183	      value = String(value);
184	    }
185	    display.textContent = text;
186	    display.setAttribute('data-value', value);
187	    display.setAttribute('data-error', state.error ? 'true' : 'false');
188	    display.setAttribute('data-open-groups', String(state.groups.length));
189	    groupsEl.textContent = new Array(state.groups.length + 1).join('(');
190	    display.classList.toggle('small', text.length > 9 && text.length <= 13);
191	    display.classList.toggle('tiny', text.length > 13);
192	    for (var i = 0; i < opButtons.length; i++) {
193	      var b = opButtons[i];
194	      b.classList.toggle('active', !hasEntry() && state.op === b.getAttribute('data-op'));
195	    }
196	  }
197	
198	  function setResult(n) {
199	    if (!isFinite(n)) {
200	      reset();
201	      state.error = true;
202	    } else {
203	      state.value = n;
204	    }
205	  }
206	
207	  function inputDigit(d) {
208	    if (!state.typing) {
209	      state.entry = d;
210	      state.typing = true;
211	      state.edited = false;
212	      if (state.op === null) state.lastOp = null;
213	    } else if (state.entry === '0' || state.entry === '-0') {
214	      state.entry = state.entry.slice(0, -1) + d;
215	    } else if (state.entry.replace(/[-.]/g, '').length < 16) {
216	      state.entry += d;
217	    }
218	  }
219	
220	  function inputDot() {
221	    if (!state.typing) {
222	      state.entry = '0.';
223	      state.typing = true;
224	      state.edited = false;
225	      if (state.op === null) state.lastOp = null;
226	    } else if (state.entry.indexOf('.') === -1) {
227	      state.entry += '.';
228	    }
229	  }
230	
231	  // ± acts on the current entry at once. While typing, ± keeps the
232	  // entry editable. Otherwise the displayed value becomes the entry, so
233	  // after an operator it is the right operand: 5 + ± = is 0.
234	  function toggleSign() {
235	    if (state.typing) {
236	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
237	    } else if (state.value === 0) {
238	      // Start a negative entry: ± 5 is -5.
239	      state.entry = '-0';
240	      state.typing = true;
241	      state.edited = false;
242	      if (state.op === null) state.lastOp = null;
243	    } else {
244	      state.value = -state.value;
245	      state.edited = true;
246	    }
247	  }
248	
249	  // Immediate execution, strictly left to right, no operator precedence:
250	  // 2 + 3 × 4 = is 20. An operator key first finishes the operation already
251	  // waiting, so the display always shows a real running result.
252	  function inputOp(op) {
253	    var v = currentValue();
254	    if (state.op !== null && hasEntry()) {
255	      setResult(compute(state.stored, state.op, v));
256	      if (state.error) return;
257	    } else {
258	      state.value = v;
259	    }
260	    state.stored = state.value;
261	    state.op = op;
262	    state.typing = false;
263	    state.edited = false;
264	    state.lastOp = null;
265	  }
266	
267	  // Parentheses keep immediate execution. ( saves the waiting operation and
268	  // starts a fresh calculation, like a new number would. ) finishes that
269	  // calculation, restores the saved operation, and leaves the group result
270	  // as the entry: 2 + ( 3 × 4 ) = is 14. Groups nest.
271	  function openGroup() {
272	    state.groups.push({ stored: state.stored, op: state.op });
273	    state.stored = null;
274	    state.op = null;
275	    state.value = 0;
276	    state.typing = false;
277	    state.edited = false;
278	    state.lastOp = null;
279	  }
280	
281	  function closeGroup() {
282	    if (state.groups.length === 0) return;
283	    if (state.op !== null && hasEntry()) {
284	      setResult(compute(state.stored, state.op, currentValue()));
285	      if (state.error) return;
286	    } else {
287	      state.value = currentValue();
288	    }
289	    var saved = state.groups.pop();
290	    state.stored = saved.stored;
291	    state.op = saved.op;
292	    state.typing = false;
293	    state.edited = true;
294	    state.lastOp = null;
295	  }
296	
297	  function equals() {
298	    // = closes any groups still open.
299	    while (state.groups.length > 0 && !state.error) closeGroup();
300	    if (state.error) return;
301	    if (state.op !== null) {
302	      var b = hasEntry() ? currentValue() : state.stored;
303	      state.lastOp = state.op;
304	      state.lastOperand = b;
305	      setResult(compute(state.stored, state.op, b));
306	    } else if (state.lastOp !== null) {
307	      setResult(compute(currentValue(), state.lastOp, state.lastOperand));
308	    } else {
309	      state.value = currentValue();
310	    }
311	    if (state.error) return;
312	    state.op = null;
313	    state.stored = null;
314	    state.typing = false;
315	    state.edited = false;
316	  }
317	
318	  function handle(el) {
319	    var digit = el.getAttribute('data-digit');
320	    var op = el.getAttribute('data-op');
321	    var action = el.getAttribute('data-action');
322	    // In the error state only clear does anything.
323	    if (state.error && action !== 'clear') return;
324	    if (digit !== null) inputDigit(digit);
325	    else if (op !== null) inputOp(op);
326	    else if (action === 'dot') inputDot();
327	    else if (action === 'sign') toggleSign();
328	    else if (action === 'lparen') openGroup();
329	    else if (action === 'rparen') closeGroup();
330	    else if (action === 'equals') equals();
331	    else if (action === 'clear') reset();
332	    render();
333	  }
334	
335	  document.querySelector('.keys').addEventListener('click', function (e) {
336	    var el = e.target.closest('button');
337	    if (el) handle(el);
338	  });
339	
340	  var keyMap = {
341	    '+': 'key-add', '-': 'key-sub', '*': 'key-mul', 'x': 'key-mul', '/': 'key-div',
342	    '.': 'key-dot', '(': 'key-lparen', ')': 'key-rparen', ',': 'key-dot', '=': 'key-equals', 'Enter': 'key-equals',
343	    'Escape': 'key-clear', 'c': 'key-clear', 'C': 'key-clear', 'Delete': 'key-clear'
344	  };
345	  document.addEventListener('keydown', function (e) {
346	    if (e.ctrlKey || e.metaKey || e.altKey) return;
347	    var id = /^[0-9]$/.test(e.key) ? 'key-' + e.key : keyMap[e.key];
348	    if (!id) return;
349	    e.preventDefault();
350	    handle(document.querySelector('[data-testid="' + id + '"]'));
351	  });
352	
353	  reset();
354	  render();
355	})();
356	</script>
357	</body>
358	</html>

